<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Entrar – Clínica Vida em Movimento Fisioterapia</title>
  <style>
    *, *::before, *::after { box-sizing: border-box; }

    body {
      margin: 0;
      min-height: 100vh;
      display: flex;
      align-items: center;
      justify-content: center;
      padding: 24px 16px;
      background: #eff6ff;
      color: #1f2937;
      font-family: system-ui, -apple-system, "Segoe UI", Roboto, Arial, sans-serif;
      font-size: 16px;
      line-height: 1.5;
    }

    main {
      width: 100%;
      max-width: 400px;
      background: #ffffff;
      border: 1px solid #d1d5db;
      border-radius: 8px;
      padding: 32px 24px;
    }

    .logo {
      display: block;
      width: 56px;
      height: 56px;
      margin: 0 auto 16px;
    }

    h1 {
      margin: 0 0 8px;
      font-size: 1.75rem;
      line-height: 1.3;
      text-align: center;
      color: #1e3a8a;
    }

    .intro {
      margin: 0 0 24px;
      text-align: center;
      color: #374151;
    }

    .field { margin-bottom: 24px; }

    label {
      display: block;
      margin-bottom: 8px;
      font-weight: 600;
      color: #1f2937;
    }

    input {
      width: 100%;
      height: 48px;
      padding: 8px 16px;
      font: inherit;
      font-size: 16px;
      color: #1f2937;
      background: #ffffff;
      border: 2px solid #6b7280;
      border-radius: 8px;
    }

    input::placeholder { color: #6b7280; opacity: 1; }

    .password-wrap { position: relative; }
    .password-wrap input { padding-right: 64px; }

    .toggle {
      position: absolute;
      top: 4px;
      right: 4px;
      width: 48px;
      height: 40px;
      padding: 0;
      font: inherit;
      font-size: 14px;
      font-weight: 600;
      color: #1d4ed8;
      background: transparent;
      border: 0;
      border-radius: 6px;
      cursor: pointer;
    }

    input:focus, .toggle:focus, a:focus, button:focus {
      outline: 3px solid #1d4ed8;
      outline-offset: 2px;
    }

    input[aria-invalid="true"] { border-color: #b91c1c; }

    .error {
      margin: 8px 0 0;
      color: #b91c1c;
      font-weight: 600;
    }
    .error:empty { display: none; }

    .btn-primary {
      width: 100%;
      height: 48px;
      font: inherit;
      font-size: 16px;
      font-weight: 700;
      color: #ffffff;
      background: #1d4ed8;
      border: 2px solid #1d4ed8;
      border-radius: 8px;
      cursor: pointer;
    }
    .btn-primary:hover { background: #1e40af; border-color: #1e40af; }

    .links {
      display: flex;
      flex-direction: column;
      align-items: center;
      gap: 8px;
      margin-top: 24px;
      text-align: center;
    }

    a {
      display: inline-block;
      min-height: 44px;
      line-height: 44px;
      color: #1d4ed8;
      text-decoration: underline;
    }
  </style>
</head>
<body>
  <main>
    <img class="logo" alt="Logotipo da Clínica Vida em Movimento Fisioterapia"
      src="data:image/svg+xml;utf8,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 56 56'%3E%3Ccircle cx='28' cy='28' r='28' fill='%231d4ed8'/%3E%3Cpath d='M28 14v28M14 28h28' stroke='white' stroke-width='6' stroke-linecap='round'/%3E%3C/svg%3E">

    <h1>Entrar</h1>
    <p class="intro">Acesse sua conta para agendar e acompanhar suas consultas de fisioterapia.</p>

    <form id="login" action="/entrar" method="post" novalidate>
      <div class="field">
        <label for="email">E-mail</label>
        <input type="email" id="email" name="email" autocomplete="username"
          placeholder="exemplo@email.com" required aria-required="true"
          aria-describedby="erro-email">
        <p class="error" id="erro-email" role="alert"></p>
      </div>

      <div class="field">
        <label for="senha">Senha</label>
        <div class="password-wrap">
          <input type="password" id="senha" name="senha" autocomplete="current-password"
            placeholder="Digite sua senha" required aria-required="true"
            aria-describedby="erro-senha">
          <button type="button" class="toggle" id="toggle" aria-label="Mostrar senha"
            aria-controls="senha">Mostrar</button>
        </div>
        <p class="error" id="erro-senha" role="alert"></p>
      </div>

      <button type="submit" class="btn-primary">Entrar</button>
    </form>

    <div class="links">
      <a href="/recuperar">Esqueci minha senha</a>
      <a href="/cadastro">Ainda não tenho conta</a>
    </div>
  </main>

  <script>
    (function () {
      var form = document.getElementById('login');
      var email = document.getElementById('email');
      var senha = document.getElementById('senha');
      var toggle = document.getElementById('toggle');

      toggle.addEventListener('click', function () {
        var mostrar = senha.type === 'password';
        senha.type = mostrar ? 'text' : 'password';
        toggle.textContent = mostrar ? 'Ocultar' : 'Mostrar';
        toggle.setAttribute('aria-label', mostrar ? 'Ocultar senha' : 'Mostrar senha');
      });

      function setErro(campo, id, msg) {
        var el = document.getElementById(id);
        el.textContent = msg ? 'Erro: ' + msg : '';
        if (msg) { campo.setAttribute('aria-invalid', 'true'); }
        else { campo.removeAttribute('aria-invalid'); }
        return !msg;
      }

      form.addEventListener('submit', function (e) {
        var msgEmail = '';
        if (!email.value.trim()) msgEmail = 'informe seu e-mail.';
        else if (!email.validity.valid) msgEmail = 'informe um e-mail válido, como exemplo@email.com.';
        var msgSenha = senha.value ? '' : 'informe sua senha.';

        var okEmail = setErro(email, 'erro-email', msgEmail);
        var okSenha = setErro(senha, 'erro-senha', msgSenha);

