<script>
  (function () {
    var form = document.querySelector("form");
    var email = document.getElementById("email");
    var senha = document.getElementById("senha");
    var erroEmail = document.getElementById("erro-email");
    var erroSenha = document.getElementById("erro-senha");
    var botao = document.getElementById("ver-senha");

    botao.addEventListener("click", function () {
      var oculto = senha.type === "password";
      senha.type = oculto ? "text" : "password";
      botao.textContent = oculto ? "Ocultar" : "Mostrar";
    });

    function mostrar(campo, area, msg) {
      area.textContent = msg;
      if (msg) { campo.setAttribute("aria-invalid", "true"); }
      else { campo.removeAttribute("aria-invalid"); }
    }

    function validarEmail() {
      var msg = "";
      if (!email.value.trim()) { msg = "Informe seu e-mail."; }
      else if (!email.checkValidity()) { msg = "Informe um e-mail válido, como nome@exemplo.com.br."; }
      mostrar(email, erroEmail, msg);
      return !msg;
    }

    function validarSenha() {
      var msg = "";
      if (!senha.value) { msg = "Informe sua senha."; }
      else if (senha.value.length < 6) { msg = "A senha deve ter pelo menos 6 caracteres."; }
      mostrar(senha, erroSenha, msg);
      return !msg;
    }

    email.addEventListener("input", function () { if (email.getAttribute("aria-invalid")) { validarEmail(); } });
    senha.addEventListener("input", function () { if (senha.getAttribute("aria-invalid")) { validarSenha(); } });

    form.addEventListener("submit", function (e) {
      var okEmail = validarEmail();
      var okSenha = validarSenha();
      if (!okEmail || !okSenha) {
        e.preventDefault();
        (okEmail ? senha : email).focus();
      }
    });
  })();
</script>
</body>
