<script>
    (function () {
      var form = document.querySelector('form');
      var email = document.getElementById('email');
      var senha = document.getElementById('senha');
      var botao = document.getElementById('alternar-senha');
      var erroEmail = document.getElementById('erro-email');
      var erroSenha = document.getElementById('erro-senha');

      botao.addEventListener('click', function () {
        var visivel = senha.type === 'text';
        senha.type = visivel ? 'password' : 'text';
        botao.textContent = visivel ? 'Mostrar' : 'Ocultar';
        botao.setAttribute('aria-pressed', visivel ? 'false' : 'true');
      });

      function mostrar(campo, el, msg) {
        el.textContent = msg;
        el.hidden = !msg;
        if (msg) { campo.setAttribute('aria-invalid', 'true'); }
        else { campo.removeAttribute('aria-invalid'); }
      }

      function validarEmail() {
        var msg = '';
        if (!email.value.trim()) { msg = 'Erro: informe seu e-mail.'; }
        else if (!email.checkValidity()) { msg = 'Erro: informe um e-mail válido, como nome@exemplo.com.br.'; }
        mostrar(email, erroEmail, msg);
        return !msg;
      }

      function validarSenha() {
        var msg = senha.value ? '' : 'Erro: informe sua senha.';
        mostrar(senha, erroSenha, msg);
        return !msg;
      }

      email.addEventListener('blur', validarEmail);
      senha.addEventListener('blur', validarSenha);

      form.addEventListener('submit', function (e) {
        var okEmail = validarEmail();
        var okSenha = validarSenha();
        if (!okEmail || !okSenha) {
          e.preventDefault();
          (okEmail ? senha : email).focus();
        }
      });
    })();
  </script>
</body>
