      min-width: 88px;
      padding: 0 12px;
      font: inherit;
      font-weight: 600;
      color: #1d4ed8;
      background: transparent;
      border: 0;
      border-radius: 6px;
      cursor: pointer;
    }

    input:focus,
    .toggle:focus-visible,
    .submit:focus-visible,
    a:focus-visible {
      outline: 3px solid #1d4ed8;
      outline-offset: 2px;
    }

    .error {
      margin: 8px 0 0;
