  <main>
    <img class="logo" alt="Melo Labs Idiomas"
      src="data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 56 56'%3E%3Crect width='56' height='56' rx='12' fill='%231d4ed8'/%3E%3Cpath d='M12 40V16h5l11 14 11-14h5v24h-5V24L28 38 17 24v16z' fill='%23fff'/%3E%3C/svg%3E">

    <h1>Entrar</h1>
    <p class="intro">Acesse suas aulas de idiomas com seu e-mail e senha.</p>

    <form id="login" action="#" method="post" novalidate>
      <div class="field">
        <label for="email">E-mail</label>
        <input id="email" name="email" type="email" autocomplete="username"
               placeholder="nome@exemplo.com" required aria-required="true"
               aria-describedby="email-erro">
        <p id="email-erro" class="error" role="alert"></p>
      </div>

      <div class="field">
        <label for="senha">Senha</label>
        <div class="password-wrap">
          <input id="senha" name="senha" type="password" autocomplete="current-password"
                 placeholder="Digite sua senha" required aria-required="true"
                 aria-describedby="senha-erro">
          <button type="button" class="toggle" id="toggle"
                  aria-label="Mostrar senha" aria-controls="senha">Mostrar</button>
        </div>
        <p id="senha-erro" class="error" role="alert"></p>
      </div>

      <button type="submit" class="submit">Entrar</button>
    </form>

    <p class="links"><a href="/recuperar">Esqueci minha senha</a></p>
  </main>

  <script>
    (function () {
      var form = document.getElementById('login');
      var email = document.getElementById('email');
      var senha = document.getElementById('senha');
      var toggle = document.getElementById('toggle');

      toggle.addEventListener('click', function () {
        var oculto = senha.type === 'password';
        senha.type = oculto ? 'text' : 'password';
        toggle.textContent = oculto ? 'Ocultar' : 'Mostrar';
        toggle.setAttribute('aria-label', oculto ? 'Ocultar senha' : 'Mostrar senha');
      });

      function validar(campo, erroId, msgVazio, msgInvalido) {
        var erro = document.getElementById(erroId);
        var msg = '';
        if (!campo.value.trim()) msg = msgVazio;
        else if (campo.validity.typeMismatch) msg = msgInvalido;
        erro.textContent = msg ? 'Erro: ' + msg : '';
        campo.setAttribute('aria-invalid', msg ? 'true' : 'false');
        return !msg;
      }

      form.addEventListener('submit', function (e) {
        var okEmail = validar(email, 'email-erro', 'informe seu e-mail.', 'informe um e-mail válido, como nome@exemplo.com.');
        var okSenha = validar(senha, 'senha-erro', 'informe sua senha.', '');
        if (!okEmail || !okSenha) {
          e.preventDefault();
          (okEmail ? senha : email).focus();
        }
      });
    })();
  </script>
</body>
</html>
