<body>
  <main>
    <div class="marca">
      <img alt="Folha Viva Plantas" src="data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 40 40'%3E%3Ccircle cx='20' cy='20' r='20' fill='%2314532d'/%3E%3Cpath d='M20 32V18M20 22c-6 0-9-4-9-9 6 0 9 3 9 9zm0 2c0-5 3-8 9-8 0 5-3 8-9 8z' fill='none' stroke='%23fff' stroke-width='2' stroke-linecap='round' stroke-linejoin='round'/%3E%3C/svg%3E">
      <span>Folha Viva Plantas</span>
    </div>

    <h1>Entrar</h1>
    <p class="intro">Acesse sua conta para acompanhar seus pedidos.</p>

    <form id="form-login" action="/entrar" method="post" novalidate>
      <div class="campo">
        <label for="email">E-mail <span class="obrigatorio" aria-hidden="true">*</span></label>
        <input id="email" name="email" type="email" autocomplete="username"
               placeholder="exemplo@email.com.br" required aria-required="true"
               aria-describedby="email-erro">
        <p id="email-erro" class="erro" role="alert"></p>
      </div>

      <div class="campo">
        <label for="senha">Senha <span class="obrigatorio" aria-hidden="true">*</span></label>
        <div class="senha-grupo">
          <input id="senha" name="senha" type="password" autocomplete="current-password"
                 placeholder="Digite sua senha" required aria-required="true"
                 aria-describedby="senha-erro">
          <button type="button" class="ver-senha" id="ver-senha" aria-label="Mostrar senha" aria-pressed="false">
            <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">
              <path d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8S1 12 1 12z"/>
              <circle cx="12" cy="12" r="3"/>
            </svg>
          </button>
        </div>
        <p id="senha-erro" class="erro" role="alert"></p>
      </div>

      <button type="submit" class="botao-primario">Entrar</button>
    </form>

    <div class="links">
      <a href="/recuperar-senha">Esqueci minha senha</a>
      <a href="/cadastro">Ainda não tenho conta</a>
    </div>
  </main>

  <script>
    (function () {
      var form = document.getElementById('form-login');
      var email = document.getElementById('email');
      var senha = document.getElementById('senha');
      var botao = document.getElementById('ver-senha');

      botao.addEventListener('click', function () {
        var mostrar = senha.type === 'password';
        senha.type = mostrar ? 'text' : 'password';
        botao.setAttribute('aria-label', mostrar ? 'Ocultar senha' : 'Mostrar senha');
        botao.setAttribute('aria-pressed', String(mostrar));
      });

      function validar(campo, msgVazio, msgInvalido) {
        var erro = document.getElementById(campo.id + '-erro');
        var msg = '';
        if (!campo.value.trim()) msg = msgVazio;
        else if (!campo.checkValidity()) msg = msgInvalido;
        erro.textContent = msg ? '⚠ ' + msg : '';
        campo.setAttribute('aria-invalid', msg ? 'true' : 'false');
        return !msg;
      }

      form.addEventListener('submit', function (e) {
        var okEmail = validar(email, 'Informe seu e-mail.', 'Informe um e-mail válido, como exemplo@email.com.br.');
        var okSenha = validar(senha, 'Informe sua senha.', 'Senha inválida.');
        if (!okEmail || !okSenha) {
          e.preventDefault();
          (okEmail ? senha : email).focus();
        }
      });
    })();
  </script>
</body>
</html>
