<script>
  (function(){
    var form = document.getElementById('form-login');
    var email = document.getElementById('email');
    var senha = document.getElementById('senha');
    var botao = document.getElementById('mostrar-senha');

    botao.addEventListener('click', function(){
      var oculta = senha.type === 'password';
      senha.type = oculta ? 'text' : 'password';
      botao.textContent = oculta ? 'Ocultar' : 'Mostrar';
      botao.setAttribute('aria-pressed', oculta ? 'true' : 'false');
    });

    function validar(campo, erroId, msgVazio, msgInvalido){
      var el = document.getElementById(erroId);
      var msg = '';
      if (!campo.value.trim()) msg = msgVazio;
      else if (!campo.checkValidity()) msg = msgInvalido;
      el.textContent = msg;
      if (msg) campo.setAttribute('aria-invalid','true');
      else campo.removeAttribute('aria-invalid');
      return !msg;
    }

    form.addEventListener('submit', function(e){
      var okEmail = validar(email, 'erro-email', 'Informe seu e-mail.', 'Informe um e-mail válido, como nome@exemplo.com.br.');
      var okSenha = validar(senha, 'erro-senha', 'Informe sua senha.', 'Senha inválida.');
      if (!okEmail || !okSenha){
        e.preventDefault();
        (okEmail ? senha : email).focus();
      }
    });
  })();
