  <main>
    <img class="logo" alt="Melo Labs"
      src="data:image/svg+xml;charset=utf-8,%3Csvg xmlns='http://www.w3.org/2000/svg' width='160' height='40' viewBox='0 0 160 40'%3E%3Crect width='40' height='40' rx='8' fill='%231d4ed8'/%3E%3Cpath d='M16 12l-8 8 8 8M24 12l8 8-8 8' fill='none' stroke='%23fff' stroke-width='3' stroke-linecap='round' stroke-linejoin='round'/%3E%3Ctext x='50' y='27' font-family='Arial,sans-serif' font-size='20' font-weight='700' fill='%231f2937'%3EMelo Labs%3C/text%3E%3C/svg%3E">

    <h1>Entrar</h1>
    <p class="intro">Acesse sua conta para retomar seus cursos de programação de onde parou.</p>

    <form id="form-login" action="/entrar" method="post" novalidate>
      <div class="campo">
        <label for="email">E-mail</label>
        <input type="email" id="email" name="email" autocomplete="username"
               placeholder="nome@exemplo.com.br" required aria-required="true"
               aria-describedby="erro-email">
        <p id="erro-email" class="erro" role="alert"></p>
      </div>

      <div class="campo">
        <label for="senha">Senha</label>
        <div class="senha-wrap">
          <input type="password" id="senha" name="senha" autocomplete="current-password"
                 placeholder="Digite sua senha" required aria-required="true"
                 aria-describedby="erro-senha">
          <button type="button" class="toggle" id="toggle-senha"
                  aria-label="Mostrar senha" aria-controls="senha" aria-pressed="false">
            <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">
              <path d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z"></path>
              <circle cx="12" cy="12" r="3"></circle>
            </svg>
          </button>
        </div>
        <p id="erro-senha" class="erro" role="alert"></p>
      </div>

      <button type="submit" class="btn-primario">Entrar</button>
    </form>

    <p class="links esqueci"><a href="/recuperar">Esqueci minha senha</a></p>
    <p class="links" style="margin-top:0">
      <span>Ainda não tem conta? <a href="/cadastro">Criar conta</a></span>
    </p>
  </main>

  <script>
    (function () {
      var form = document.getElementById('form-login');
      var email = document.getElementById('email');
      var senha = document.getElementById('senha');
      var erroEmail = document.getElementById('erro-email');
      var erroSenha = document.getElementById('erro-senha');
      var toggle = document.getElementById('toggle-senha');

      toggle.addEventListener('click', function () {
        var mostrar = senha.type === 'password';
        senha.type = mostrar ? 'text' : 'password';
        toggle.setAttribute('aria-label', mostrar ? 'Ocultar senha' : 'Mostrar senha');
        toggle.setAttribute('aria-pressed', mostrar ? 'true' : 'false');
      });

      form.addEventListener('submit', function (e) {
        var ok = true;
        erroEmail.textContent = '';
        erroSenha.textContent = '';
        email.removeAttribute('aria-invalid');
        senha.removeAttribute('aria-invalid');

        if (!email.value.trim()) {
          erroEmail.textContent = 'Erro: informe seu e-mail.';
          email.setAttribute('aria-invalid', 'true');
          ok = false;
        } else if (!email.validity.valid) {
          erroEmail.textContent = 'Erro: informe um e-mail válido, como nome@exemplo.com.br.';
          email.setAttribute('aria-invalid', 'true');
          ok = false;
        }
        if (!senha.value) {
          erroSenha.textContent = 'Erro: informe sua senha.';
          senha.setAttribute('aria-invalid', 'true');
          ok = false;
        }
        if (!ok) {
          e.preventDefault();
          (email.getAttribute('aria-invalid') ? email : senha).focus();
        }
      });
    })();
  </script>
</body>
