        var erro = document.getElementById(campo.id + '-erro');
        var msg;
        if (campo.validity.valueMissing) {
          msg = campo.type === 'email' ? 'Informe seu e-mail.' : 'Informe sua senha.';
        } else {
          msg = 'Informe um e-mail válido, como nome@exemplo.com.br.';
        }
        erro.textContent = '⚠ ' + msg;
        campo.parentNode.classList.add('invalido');
        campo.closest('.campo').classList.add('invalido');
        if (!focou) {
          focou = true;
          campo.focus();
          setTimeout(function () { focou = false; }, 0);
        }
      }, true);

      form.addEventListener('input', function (e) {
        var erro = document.getElementById(e.target.id + '-erro');
        if (erro) { erro.textContent = ''; }
        e.target.closest('.campo').classList.remove('invalido');
      });
    })();
  </script>
