      var senhaErro = document.getElementById('senha-erro');
      var botao = document.getElementById('alternar-senha');

      botao.addEventListener('click', function () {
        var oculta = senha.type === 'password';
        senha.type = oculta ? 'text' : 'password';
        botao.textContent = oculta ? 'Ocultar' : 'Mostrar';
        botao.setAttribute('aria-label', oculta ? 'Ocultar senha' : 'Mostrar senha');
        botao.setAttribute('aria-pressed', oculta ? 'true' : 'false');
      });

      function validar(campo, erro, vazio, invalido) {
        var msg = '';
        if (campo.validity.valueMissing) { msg = vazio; }
        else if (invalido && campo.validity.typeMismatch) { msg = invalido; }
        erro.textContent = msg ? 'Erro: ' + msg : '';
        campo.setAttribute('aria-invalid', msg ? 'true' : 'false');
        return !msg;
