               placeholder="nome@exemplo.com" required aria-required="true"
               aria-describedby="erro-email">
        <p class="erro" id="erro-email" role="alert"></p>
      </div>

      <div class="campo">
        <label for="senha">Senha</label>
        <div class="senha-wrap">
          <input type="password" id="senha" name="senha" autocomplete="current-password"
                 required aria-required="true" aria-describedby="erro-senha">
          <button type="button" class="ver-senha" id="ver-senha"
                  aria-label="Mostrar senha" aria-pressed="false">
            <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">
              <path d="M1 12s4-7 11-7 11 7 11 7-4 7-11 7S1 12 1 12z"/>
              <circle cx="12" cy="12" r="3"/>
            </svg>
          </button>
        </div>
        <p class="erro" id="erro-senha" role="alert"></p>
      </div>

      <button type="submit" class="primario">Entrar</button>

      <p class="links"><a href="/recuperar">Esqueci minha senha</a></p>
    </form>
  </main>

  <script>
    (function () {
      var form = document.getElementById('login');
      var email = document.getElementById('email');
      var senha = document.getElementById('senha');
      var botao = document.getElementById('ver-senha');

      botao.addEventListener('click', function () {
        var oculta = senha.type === 'password';
        senha.type = oculta ? 'text' : 'password';
        botao.setAttribute('aria-label', oculta ? 'Ocultar senha' : 'Mostrar senha');
        botao.setAttribute('aria-pressed', oculta ? 'true' : 'false');
      });

      function validar(campo, erroId, vazio, invalido) {
        var el = document.getElementById(erroId);
        var msg = '';
        if (!campo.value.trim()) msg = vazio;
        else if (!campo.checkValidity()) msg = invalido;
        el.textContent = msg ? 'Erro: ' + msg : '';
        campo.setAttribute('aria-invalid', msg ? 'true' : 'false');
        return !msg;
      }

      form.addEventListener('submit', function (e) {
        var okEmail = validar(email, 'erro-email', 'informe seu e-mail.', 'informe um e-mail válido, como nome@exemplo.com.');
        var okSenha = validar(senha, 'erro-senha', 'informe sua senha.', 'senha inválida.');
        if (!okEmail || !okSenha) {
          e.preventDefault();
          (okEmail ? senha : email).focus();
        }
      });
    })();
  </script>
