    (function () {
      var form = document.querySelector('form');
      var email = document.getElementById('email');
      var senha = document.getElementById('senha');
      var toggle = document.getElementById('toggle-senha');

      toggle.addEventListener('click', function () {
        var mostrar = senha.type === 'password';
        senha.type = mostrar ? 'text' : 'password';
        toggle.textContent = mostrar ? 'Ocultar' : 'Mostrar';
      });

      function setErro(input, id, msg) {
        document.getElementById(id).textContent = msg;
        if (msg) { input.setAttribute('aria-invalid', 'true'); }
        else { input.removeAttribute('aria-invalid'); }
      }

      form.addEventListener('submit', function (e) {
        var m1 = '';
        var m2 = '';
        if (!email.value.trim()) { m1 = 'Erro: informe seu e-mail.'; }
        else if (!email.checkValidity()) { m1 = 'Erro: digite um e-mail válido, como nome@exemplo.com.'; }
        if (!senha.value) { m2 = 'Erro: informe sua senha.'; }
        setErro(email, 'email-erro', m1);
        setErro(senha, 'senha-erro', m2);
        if (m1 || m2) {
          e.preventDefault();
          (m1 ? email : senha).focus();
        }
      });
    })();
