<script>
    (function () {
      var form = document.querySelector('form');
      var email = document.getElementById('email');
      var senha = document.getElementById('senha');
      var toggle = document.querySelector('.mostrar');

      toggle.addEventListener('click', function () {
        var visivel = senha.type === 'text';
        senha.type = visivel ? 'password' : 'text';
        toggle.textContent = visivel ? 'Mostrar' : 'Ocultar';
        toggle.setAttribute('aria-pressed', String(!visivel));
      });

      function mostrarErro(campo, msg) {
        var el = document.getElementById('erro-' + campo.id);
        if (msg) {
          el.textContent = msg;
          el.hidden = false;
          campo.setAttribute('aria-invalid', 'true');
        } else {
          el.textContent = '';
          el.hidden = true;
          campo.removeAttribute('aria-invalid');
        }
        return !msg;
      }

      function validarEmail() {
        if (!email.value.trim()) return mostrarErro(email, 'Informe seu e-mail.');
        if (!email.validity.valid) return mostrarErro(email, 'Informe um e-mail válido, como nome@empresa.com.br.');
        return mostrarErro(email, '');
      }

      function validarSenha() {
        return mostrarErro(senha, senha.value ? '' : 'Informe sua senha.');
      }

      email.addEventListener('blur', validarEmail);
      senha.addEventListener('blur', validarSenha);

      form.addEventListener('submit', function (e) {
        var okEmail = validarEmail();
        var okSenha = validarSenha();
        if (!okEmail || !okSenha) {
          e.preventDefault();
          (okEmail ? senha : email).focus();
        }
      });
    })();
  </script>
</body>
