  <main>
    <img class="logo" alt="Biblioteca Municipal"
         src="data:image/svg+xml;utf8,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 56 56'%3E%3Crect width='56' height='56' rx='8' fill='%231e3a8a'/%3E%3Cpath d='M12 16h13a3 3 0 0 1 3 3v21a3 3 0 0 0-3-3H12zM44 16H31a3 3 0 0 0-3 3v21a3 3 0 0 1 3-3h13z' fill='%23fff'/%3E%3C/svg%3E">

    <h1>Entrar</h1>
    <p class="intro">Acesse sua conta de leitor para renovar seus empréstimos.</p>

    <form id="form-login" action="/entrar" method="post" novalidate>
      <div class="campo">
        <label for="email">E-mail</label>
        <input type="email" id="email" name="email" autocomplete="username"
               placeholder="exemplo@email.com" required aria-required="true"
               aria-describedby="erro-email">
        <p class="erro" id="erro-email" role="alert"></p>
      </div>

      <div class="campo">
        <label for="senha">Senha</label>
        <div class="senha-wrap">
          <input type="password" id="senha" name="senha" autocomplete="current-password"
                 required aria-required="true" aria-describedby="erro-senha">
          <button type="button" class="mostrar" id="alternar"
                  aria-label="Mostrar senha" aria-controls="senha">Mostrar</button>
        </div>
        <p class="erro" id="erro-senha" role="alert"></p>
      </div>

      <button type="submit" class="entrar">Entrar</button>
    </form>

    <p class="links"><a href="/recuperar">Esqueci minha senha</a></p>
  </main>

  <script>
    (function () {
      var form = document.getElementById('form-login');
      var email = document.getElementById('email');
      var senha = document.getElementById('senha');
      var btn = document.getElementById('alternar');

      btn.addEventListener('click', function () {
        var oculto = senha.type === 'password';
        senha.type = oculto ? 'text' : 'password';
        btn.textContent = oculto ? 'Ocultar' : 'Mostrar';
        btn.setAttribute('aria-label', oculto ? 'Ocultar senha' : 'Mostrar senha');
      });

      function validar(campo, erroId, vazio, invalido) {
        var el = document.getElementById(erroId);
        var msg = '';
        if (!campo.value.trim()) msg = vazio;
        else if (!campo.checkValidity()) msg = invalido;
        el.textContent = msg ? '⚠ ' + msg : '';
        if (msg) campo.setAttribute('aria-invalid', 'true');
        else campo.removeAttribute('aria-invalid');
        return !msg;
      }

      form.addEventListener('submit', function (e) {
        var okEmail = validar(email, 'erro-email', 'Informe seu e-mail.', 'Informe um e-mail válido, como nome@exemplo.com.');
        var okSenha = validar(senha, 'erro-senha', 'Informe sua senha.', 'Senha inválida.');
        if (!okEmail || !okSenha) {
          e.preventDefault();
          (okEmail ? senha : email).focus();
        }
      });
    })();
  </script>
</body>
