<body>
  <main>
    <p class="marca">
      <svg width="32" height="32" viewBox="0 0 32 32" aria-hidden="true" focusable="false">
        <rect x="4" y="5" width="6" height="22" rx="1" fill="#1d4ed8"/>
        <rect x="12" y="5" width="6" height="22" rx="1" fill="#1e3a8a"/>
        <rect x="20" y="8" width="6" height="19" rx="1" fill="#374151" transform="rotate(-10 23 17)"/>
      </svg>
      Biblioteca Municipal
    </p>

    <h1>Entrar</h1>
    <p class="intro">Acesse sua conta de leitor para renovar seus empréstimos.</p>

    <form id="form-login" action="/entrar" method="post">
      <div class="campo">
        <label for="email">E-mail</label>
        <input type="email" id="email" name="email" autocomplete="username"
               placeholder="exemplo: maria@email.com.br" required aria-required="true"
               aria-describedby="erro-email">
        <p class="erro" id="erro-email" role="alert"></p>
      </div>

      <div class="campo">
        <label for="senha">Senha</label>
        <div class="senha-wrap">
          <input type="password" id="senha" name="senha" autocomplete="current-password"
                 required aria-required="true" aria-describedby="erro-senha">
          <button type="button" class="alternar" id="alternar"
                  aria-label="Mostrar senha" aria-controls="senha">Mostrar</button>
        </div>
        <p class="erro" id="erro-senha" role="alert"></p>
      </div>

      <button type="submit" class="primario">Entrar</button>
    </form>

    <p class="links"><a href="/recuperar">Esqueci minha senha</a></p>
  </main>

  <script>
    (function () {
      var form = document.getElementById('form-login');
      var senha = document.getElementById('senha');
      var botao = document.getElementById('alternar');

      botao.addEventListener('click', function () {
        var oculta = senha.type === 'password';
        senha.type = oculta ? 'text' : 'password';
        botao.textContent = oculta ? 'Ocultar' : 'Mostrar';
        botao.setAttribute('aria-label', oculta ? 'Ocultar senha' : 'Mostrar senha');
      });

      var mensagens = {
        email: {
          valueMissing: 'Erro: informe seu e-mail.',
          typeMismatch: 'Erro: digite um e-mail válido, como maria@email.com.br.'
        },
        senha: { valueMissing: 'Erro: informe sua senha.' }
      };

      form.addEventListener('invalid', function (e) {
        e.preventDefault();
        var campo = e.target;
        var tipo = campo.validity.valueMissing ? 'valueMissing' : 'typeMismatch';
        var texto = (mensagens[campo.name] || {})[tipo] || 'Erro: verifique este campo.';
        document.getElementById('erro-' + campo.name).textContent = texto;
        campo.setAttribute('aria-invalid', 'true');
        var primeiro = form.querySelector('[aria-invalid="true"]');
        if (primeiro) primeiro.focus();
      }, true);

      form.addEventListener('input', function (e) {
        var campo = e.target;
        document.getElementById('erro-' + campo.name).textContent = '';
        campo.removeAttribute('aria-invalid');
      });
    })();
  </script>
</body>
