        <path d="M16 25V12M16 16c-4 0-6-2-6-5 4 0 6 2 6 5zm0 3c4 0 6-2 6-5-4 0-6 2-6 5z" fill="none" stroke="#fff" stroke-width="2" stroke-linecap="round"/>
      </svg>
      <span>Cooperativa Agrícola</span>
    </p>

    <h1>Entrar</h1>
    <p class="intro">Acesse sua conta de cooperado para acompanhar suas entregas.</p>

    <form id="login" action="/entrar" method="post" novalidate>
      <div class="campo">
        <label for="email">E-mail</label>
        <input type="email" id="email" name="email" autocomplete="username" placeholder="nome@exemplo.com.br" required aria-required="true" aria-describedby="erro-email">
        <p class="erro" id="erro-email" role="alert"></p>
      </div>

      <div class="campo">
        <label for="senha">Senha</label>
        <div class="senha">
          <input type="password" id="senha" name="senha" autocomplete="current-password" placeholder="Digite sua senha" required aria-required="true" aria-describedby="erro-senha">
          <button type="button" class="mostrar" id="alternar" aria-label="Mostrar senha" aria-pressed="false">
            <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false">
              <path d="M1 12s4-7 11-7 11 7 11 7-4 7-11 7S1 12 1 12z"/>
              <circle cx="12" cy="12" r="3"/>
            </svg>
          </button>
        </div>
        <p class="erro" id="erro-senha" role="alert"></p>
      </div>

      <button type="submit" class="entrar">Entrar</button>
    </form>

    <p class="apoio"><a href="/recuperar">Esqueci minha senha</a></p>
  </main>

  <script>
    (function () {
      var form = document.getElementById('login');
      var email = document.getElementById('email');
      var senha = document.getElementById('senha');
      var botao = document.getElementById('alternar');

      botao.addEventListener('click', function () {
        var oculto = senha.type === 'password';
        senha.type = oculto ? 'text' : 'password';
        botao.setAttribute('aria-label', oculto ? 'Ocultar senha' : 'Mostrar senha');
        botao.setAttribute('aria-pressed', oculto ? 'true' : 'false');
      });

      function validar(campo, erroId, vazio, invalido) {
        var erro = document.getElementById(erroId);
        var msg = '';
        if (!campo.value.trim()) { msg = vazio; }
        else if (!campo.checkValidity()) { msg = invalido; }
        erro.textContent = msg ? 'Erro: ' + msg : '';
        campo.setAttribute('aria-invalid', msg ? 'true' : 'false');
        return !msg;
      }

      form.addEventListener('submit', function (e) {
        var okEmail = validar(email, 'erro-email', 'informe seu e-mail.', 'informe um e-mail válido, como nome@exemplo.com.br.');
        var okSenha = validar(senha, 'erro-senha', 'informe sua senha.', 'informe sua senha.');
        if (!okEmail || !okSenha) {
          e.preventDefault();
          (okEmail ? senha : email).focus();
        }
      });
    })();
  </script>
