  <script>
    (function () {
      var form = document.querySelector('form');
      var email = document.getElementById('email');
      var senha = document.getElementById('senha');
      var erroEmail = document.getElementById('erro-email');
      var erroSenha = document.getElementById('erro-senha');
      var toggle = document.querySelector('.ver-senha');

      toggle.addEventListener('click', function () {
        var oculto = senha.type === 'password';
        senha.type = oculto ? 'text' : 'password';
        toggle.textContent = oculto ? 'Ocultar' : 'Mostrar';
        toggle.setAttribute('aria-pressed', String(oculto));
      });

      function marcar(campo, caixa, msg) {
        caixa.textContent = msg;
        if (msg) { campo.setAttribute('aria-invalid', 'true'); }
        else { campo.removeAttribute('aria-invalid'); }
        return !msg;
      }

      form.addEventListener('submit', function (e) {
        var msgEmail = '';
        if (!email.value.trim()) { msgEmail = 'Erro: informe seu e-mail.'; }
        else if (!email.checkValidity()) { msgEmail = 'Erro: digite um e-mail válido, como seunome@exemplo.com.br.'; }
        var msgSenha = senha.value ? '' : 'Erro: informe sua senha.';
        var okEmail = marcar(email, erroEmail, msgEmail);
        var okSenha = marcar(senha, erroSenha, msgSenha);
        if (!okEmail || !okSenha) {
          e.preventDefault();
          (okEmail ? senha : email).focus();
        }
      });
    })();
  </script>
