<script>
  (function () {
    var form = document.querySelector('form');
    var email = document.getElementById('email');
    var senha = document.getElementById('senha');
    var botao = document.getElementById('alternar-senha');

    botao.addEventListener('click', function () {
      var mostrar = senha.type === 'password';
      senha.type = mostrar ? 'text' : 'password';
      botao.textContent = mostrar ? 'Ocultar' : 'Mostrar';
      botao.setAttribute('aria-pressed', String(mostrar));
      botao.setAttribute('aria-label', mostrar ? 'Ocultar senha' : 'Mostrar senha');
    });

    function mostrarErro(campo, id, msg) {
      document.getElementById(id).textContent = msg;
      if (msg) { campo.setAttribute('aria-invalid', 'true'); }
      else { campo.removeAttribute('aria-invalid'); }
      return !msg;
    }

    function validarEmail() {
      var msg = '';
      if (!email.value.trim()) { msg = 'Erro: informe seu e-mail.'; }
      else if (!email.validity.valid) { msg = 'Erro: informe um e-mail válido, como nome@exemplo.com.br.'; }
      return mostrarErro(email, 'erro-email', msg);
    }

    function validarSenha() {
      return mostrarErro(senha, 'erro-senha', senha.value ? '' : 'Erro: informe sua senha.');
    }

    email.addEventListener('input', function () { if (email.hasAttribute('aria-invalid')) validarEmail(); });
    senha.addEventListener('input', function () { if (senha.hasAttribute('aria-invalid')) validarSenha(); });

    form.addEventListener('submit', function (e) {
      var okEmail = validarEmail();
      var okSenha = validarSenha();
      if (!okEmail || !okSenha) {
        e.preventDefault();
        (okEmail ? senha : email).focus();
      }
    });
  })();
</script>
</body>
