<body>
  <main class="cartao">
    <img class="logo" alt="Melo Studio"
      src="data:image/svg+xml;utf8,%3Csvg xmlns='http://www.w3.org/2000/svg' width='160' height='40' viewBox='0 0 160 40'%3E%3Crect width='40' height='40' rx='8' fill='%231d4ed8'/%3E%3Ctext x='20' y='28' font-family='Arial' font-size='22' font-weight='700' fill='%23ffffff' text-anchor='middle'%3EM%3C/text%3E%3Ctext x='50' y='27' font-family='Arial' font-size='20' font-weight='700' fill='%23111827'%3EMelo Studio%3C/text%3E%3C/svg%3E">

    <h1>Entrar</h1>
    <p class="apoio">Acesse a área do cliente para revisar e aprovar as entregas do seu projeto.</p>

    <form id="form-login" action="/entrar" method="post" novalidate>
      <div class="campo">
        <label for="email">E-mail <span class="obrigatorio" aria-hidden="true">*</span></label>
        <input type="email" id="email" name="email" autocomplete="username"
               placeholder="nome@empresa.com.br" required aria-required="true"
               aria-describedby="erro-email">
        <p class="erro" id="erro-email" role="alert"></p>
      </div>

      <div class="campo">
        <label for="senha">Senha <span class="obrigatorio" aria-hidden="true">*</span></label>
        <div class="senha-grupo">
          <input type="password" id="senha" name="senha" autocomplete="current-password"
                 placeholder="Digite sua senha" required aria-required="true"
                 aria-describedby="erro-senha">
          <button type="button" class="mostrar" id="alternar-senha"
                  aria-label="Mostrar senha" aria-controls="senha">Mostrar</button>
        </div>
        <p class="erro" id="erro-senha" role="alert"></p>
      </div>

      <button type="submit" class="btn-primario">Entrar</button>
    </form>

    <p class="extras"><a href="/recuperar-senha">Esqueci minha senha</a></p>
  </main>

  <script>
    (function () {
      var form = document.getElementById('form-login');
      var email = document.getElementById('email');
      var senha = document.getElementById('senha');
      var botao = document.getElementById('alternar-senha');
      var erroEmail = document.getElementById('erro-email');
      var erroSenha = document.getElementById('erro-senha');

      botao.addEventListener('click', function () {
        var oculta = senha.type === 'password';
        senha.type = oculta ? 'text' : 'password';
        botao.textContent = oculta ? 'Ocultar' : 'Mostrar';
        botao.setAttribute('aria-label', oculta ? 'Ocultar senha' : 'Mostrar senha');
      });

      function validar(campo, msgEl, vazio, invalido) {
        var msg = '';
        if (campo.validity.valueMissing) msg = vazio;
        else if (campo.validity.typeMismatch) msg = invalido;
        msgEl.textContent = msg;
        campo.setAttribute('aria-invalid', msg ? 'true' : 'false');
        return !msg;
      }

      form.addEventListener('submit', function (e) {
        var okEmail = validar(email, erroEmail, 'Erro: informe seu e-mail.', 'Erro: digite um e-mail válido, como nome@empresa.com.br.');
        var okSenha = validar(senha, erroSenha, 'Erro: informe sua senha.', '');
        if (!okEmail || !okSenha) {
          e.preventDefault();
          (okEmail ? senha : email).focus();
        }
      });
    })();
  </script>
</body>
