<script>
  (function () {
    var form = document.querySelector('form');
    var email = document.getElementById('email');
    var senha = document.getElementById('senha');
    var toggle = document.getElementById('toggle-senha');

    toggle.addEventListener('click', function () {
      var oculto = senha.type === 'password';
      senha.type = oculto ? 'text' : 'password';
      toggle.textContent = oculto ? 'Ocultar' : 'Mostrar';
    });

    function validar(campo, mensagem) {
      var erro = document.getElementById(campo.id + '-erro');
      if (mensagem) {
        erro.textContent = 'Erro: ' + mensagem;
        campo.setAttribute('aria-invalid', 'true');
      } else {
        erro.textContent = '';
        campo.removeAttribute('aria-invalid');
      }
      return !mensagem;
    }

    function checaEmail() {
      var v = email.value.trim();
      if (!v) return validar(email, 'informe seu e-mail.');
      if (!email.checkValidity()) return validar(email, 'informe um e-mail válido, como voce@empresa.com.br.');
      return validar(email, '');
    }

    function checaSenha() {
      return validar(senha, senha.value ? '' : 'informe sua senha.');
    }

    email.addEventListener('blur', checaEmail);
    senha.addEventListener('blur', checaSenha);

    form.addEventListener('submit', function (e) {
      var okEmail = checaEmail();
      var okSenha = checaSenha();
      if (!okEmail || !okSenha) {
        e.preventDefault();
        (okEmail ? senha : email).focus();
      }
    });
  })();
</script>
