  .brand p {
    margin: 6px 0 0;
    font-size: .9rem;
    opacity: .92;
  }

  form { padding: 28px 28px 20px; }

  .intro {
    margin: 0 0 20px;
    color: var(--muted);
    font-size: .95rem;
    text-align: center;
  }

  .field { margin-bottom: 18px; }
  label {
    display: block;
    font-weight: 600;
    font-size: .9rem;
    margin-bottom: 6px;
  }
  input[type="email"],
  input[type="password"] {
    width: 100%;
    padding: 12px 14px;
