  .row label {
    display: flex;
    align-items: center;
    gap: 8px;
    margin: 0;
    font-weight: 400;
    cursor: pointer;
  }
  .row input[type="checkbox"] {
    width: 18px; height: 18px;
    accent-color: var(--green-dark);
  }
  a { color: var(--green-dark); font-weight: 600; text-decoration: none; }
  a:hover, a:focus-visible { text-decoration: underline; }

  button {
