  button:focus-visible { outline: 3px solid var(--gold); outline-offset: 2px; }

  .footer {
    padding: 16px 28px 26px;
    text-align: center;
    font-size: .9rem;
    color: var(--muted);
    border-top: 1px solid #e6e1d3;
  }

  @media (max-width: 420px) {
    form { padding: 24px 20px 16px; }
    .footer { padding: 16px 20px 24px; }
  }
</style>
</head>
